-- Verified access details — Bay of Islands, Morrum, Nikko (2026-07-29)
-- Includes a regulations correction for Nikko: the lake is catch-and-release
-- only, which the previous regulations did not state.
UPDATE public.spots SET access = '{"shore": true, "boat": true, "ramp": "Far North District Council maintains public ramps at Russell, Waitangi, Te Haumi, Ōpua, Tapeka Point, Rāwhiti, Rangitāne, Rangitoto (Windsor Landing), Waipapa Landing and Ōpito Bay", "facilities": ["Multiple council boat ramps", "Passenger and vehicle ferries between Paihia, Russell and Ōpua"], "notes": "Access is unusually good for a game fishery — a dense network of council ramps around the bay, plus a large charter fleet operating out of Paihia and Russell, which is how most visitors fish the offshore grounds. Northland Regional Council publishes maritime maps covering navigation and moorings. Marine reserves within the bay are no-take zones, so check the boundaries before fishing.", "sourceUrl": "https://www.fndc.govt.nz/Facilities/Maritime-Facilities-in-the-Far-North/bay-of-islands-boat-ramps"}'::jsonb, updated_at = now() WHERE slug = 'bay-of-islands-marlin';
UPDATE public.spots SET access = '{"shore": true, "notes": "The classic water is roughly 7 km of the lower river close to the Baltic, divided into 32 numbered pools. Permits are bought online or in person at Laxens Hus in Mörrum, and a digital voucher on your phone is accepted. An extended permit also covers the Vittskövle, Knaggalid and Härnäs stretches further upstream. The season runs 30 March to 30 September and fishing is permitted from 05:00 to 02:00. You must be able to produce a valid permit on the bank.", "sourceUrl": "https://www.sveaskog.se/en/morrum/on-line-booking/book-fishing-permits/day-permits/"}'::jsonb, updated_at = now() WHERE slug = 'morrum-river-salmon';
UPDATE public.spots SET access = '{"shore": true, "walkIn": "A 3 km walking trail circles Lake Yunoko, giving foot access to most of the shoreline", "notes": "IMPORTANT: fishing here is catch and release only — removing fish from the lake is strictly prohibited. A day permit costs roughly 2,000-3,600 yen depending on month and location, and the season runs May to September with fishing permitted 05:00 to 17:00. Nearby Lake Chuzenji opens on 1 April and is restricted to catch-and-release lure or fly fishing. Both lakes sit inside Nikkō National Park, so park access rules apply.", "sourceUrl": "https://www.visitnikko.jp/en/spots/lake-yunoko/"}'::jsonb, updated_at = now() WHERE slug = 'nikko-yunoko-trout';
UPDATE public.spots SET regulations = '["A yugyoken (day permit) from the local fishery is required — sold at tackle shops, convenience stores and by app","Catch and release only: removing fish from Lake Yunoko is prohibited","Season runs May to September; Nikko National Park access rules apply"]'::jsonb, updated_at = now() WHERE slug = 'nikko-yunoko-trout';
